/**
 * "Fill with AI": one tap for every word that has no meaning yet (owner,
 * 17 Oct 2026). Imports, a pasted text and the rest of a part-filled AI
 * list leave words with nothing but the headword; they wait outside
 * practice (`canPractise`) until something writes their meaning.
 *
 * Nothing new on the server: the words go to the same job endpoint as
 * "Many at once", in batches of what one job takes (`MAX_WORDS`), each with
 * `partial: true`, so the server fills what the learner's allowance has
 * left and names the rest. It enforces every limit and announces none; this
 * module only says what happened to the learner's own words.
 *
 * What the model writes is poured in with `enrichWord`, which only adds:
 * a meaning, example or note the learner already has is never replaced, and
 * a word that got a meaning some other way in the meantime is left alone.
 * The word keeps its source (import, manual), so `enrichWord` records which
 * senses the model wrote and the job that wrote them; the word page offers
 * Report on exactly those (store policies on generated content).
 *
 * Cost: no hint is ever sent, so every card can come from the shared cache
 * and feeds it. A job is remembered (meta `fillJobs`) from the moment it is
 * created until its cards are in the words, so a closed tab, a second tap or
 * a second window watches the job already asked for instead of asking for
 * the same words again; Web Locks keep two windows from filling at once.
 *
 * A word the AI declined (not a word it knows, or a card it could not write
 * twice) is remembered (meta `fillDeclined`) and never offered to the AI
 * again: the card asks for the learner's own meaning, an edit or a delete
 * instead, so it does not keep offering a button that can only fail.
 * Changing the headword or giving it a meaning lets the word go.
 */
import { create } from 'zustand';
import { firstMeaning, normalizeHeadword, type Word } from '@lexpad/core';
import { ai as aiApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { enrichWord } from '@/db/mutations.js';
import { listWords } from '@/db/repo.js';
import { getMeta, setMeta, type StoredFillJob } from '@/db/schema.js';
import { syncSoon } from '@/sync/store.js';
import { aiJobFromApi, type AiJobView } from '@/sync/mapping.js';
import { isAiConsentDeclined } from './consent.js';
import { isRunning, watchJob } from './poll.js';
import { isRefusal, noteRefusal } from './quota.js';
import { isUnwritable, missingFrom } from './generate.js';
import { MAX_WORDS } from './words.js';

/**
 * How long a remembered job is worth asking about. The server finishes a
 * job in seconds and keeps it, so a day is far past any job still running;
 * after that the words are simply asked for again.
 */
const FORGET_JOB_AFTER_MS = 24 * 60 * 60 * 1000;

/** The Web Lock one window holds while it fills, so two never ask for the same words. */
const FILL_LOCK = 'lexpad-fill-with-ai';

/**
 * How a run ended:
 * - `done`: every batch came back (some words may still have no card;
 *   `skipped` names those the AI did not know as words).
 * - `rest`: the day's AI ran out part way; the rest wait for tomorrow.
 * - `restUnconfirmed`: an unconfirmed address's few cards ran out part way.
 * - `resting`: nothing could be filled today.
 * - `unconfirmed`: nothing until the address is confirmed.
 * - `offline`, `declined` (AI consent), `failed`: what it says.
 * - `elsewhere`: another window of this app is already filling.
 */
export type FillOutcome =
  | 'done'
  | 'rest'
  | 'restUnconfirmed'
  | 'resting'
  | 'unconfirmed'
  | 'offline'
  | 'declined'
  | 'failed'
  | 'elsewhere';

/** Whether a word is waiting for a meaning: the words Today counts as unready. */
export function needsMeaning(word: Word): boolean {
  return word.headword.trim() !== '' && firstMeaning(word).trim() === '' && word.progress?.retired !== true;
}

/**
 * Every word of a notebook still waiting for a meaning, the top of the
 * notebook first, optionally only among `ids` (the words an import added).
 */
export async function waitingWords(notebookId: string, ids?: ReadonlySet<string>): Promise<Word[]> {
  const words = await listWords(notebookId);
  return words
    .filter((word) => needsMeaning(word) && (ids === undefined || ids.has(word.id)))
    .sort((a, b) => b.position - a.position);
}

/** The normalised headwords of a notebook the AI has declined. */
async function declinedKeys(notebookId: string): Promise<Set<string>> {
  const declined = await getMeta('fillDeclined');
  return new Set(declined.filter((entry) => entry.notebookId === notebookId).map((entry) => entry.key));
}

// The two queries below start both reads at once rather than one after the
// other: inside a live query, a read that follows an await of a plain async
// function can run outside Dexie's zone and go unobserved, and the card then
// kept listing words that had been deleted.

/** The waiting words the AI can still be asked for: every one it has not declined. */
export async function wordsToFill(notebookId: string, ids?: ReadonlySet<string>): Promise<Word[]> {
  const [waiting, declined] = await Promise.all([waitingWords(notebookId, ids), declinedKeys(notebookId)]);
  return waiting.filter((word) => !declined.has(normalizeHeadword(word.headword)));
}

/** The waiting words the AI declined, which need the learner's own meaning. */
export async function declinedWords(notebookId: string, ids?: ReadonlySet<string>): Promise<Word[]> {
  const [waiting, declined] = await Promise.all([waitingWords(notebookId, ids), declinedKeys(notebookId)]);
  return waiting.filter((word) => declined.has(normalizeHeadword(word.headword)));
}

/**
 * Remembers the words the AI declined in this notebook, and lets go of any
 * remembered one that no longer waits (it got a meaning, its headword was
 * edited, or it was deleted).
 */
export async function recordDeclined(
  notebookId: string,
  headwords: readonly string[],
  now: Date = new Date(),
): Promise<void> {
  const waiting = new Set((await waitingWords(notebookId)).map((word) => normalizeHeadword(word.headword)));
  const all = await getMeta('fillDeclined');
  const kept = all.filter((entry) => entry.notebookId !== notebookId || waiting.has(entry.key));
  const known = new Set(kept.filter((entry) => entry.notebookId === notebookId).map((entry) => entry.key));
  for (const headword of headwords) {
    const key = normalizeHeadword(headword);
    if (!waiting.has(key) || known.has(key)) continue;
    known.add(key);
    kept.push({ notebookId, key, at: now.toISOString() });
  }
  if (kept.length !== all.length || kept.some((entry, index) => entry !== all[index])) {
    await setMeta('fillDeclined', kept);
  }
}

/**
 * Pours a finished job's cards into the words they were asked for, matched
 * by the normalised headword, and answers how many words now have a meaning.
 * A word that found a meaning some other way meanwhile is not touched.
 */
export async function applyFill(notebookId: string, job: AiJobView): Promise<number> {
  const waiting = new Map<string, string>();
  for (const word of await listWords(notebookId)) {
    if (needsMeaning(word)) waiting.set(normalizeHeadword(word.headword), word.id);
  }
  let filled = 0;
  for (const card of job.cards) {
    const key = normalizeHeadword(card.headword);
    const id = waiting.get(key);
    if (id === undefined) continue;
    waiting.delete(key);
    // The job is recorded with what it wrote, so each meaning it poured in
    // can be reported from the word's page (the word keeps its source).
    if ((await enrichWord(id, card, undefined, job.id)) > 0) filled += 1;
  }
  if (filled > 0) void syncSoon();
  return filled;
}

async function rememberJob(job: StoredFillJob): Promise<void> {
  const jobs = await getMeta('fillJobs');
  await setMeta('fillJobs', [...jobs.filter((known) => known.id !== job.id), job]);
}

async function forgetJob(id: string): Promise<void> {
  const jobs = await getMeta('fillJobs');
  await setMeta(
    'fillJobs',
    jobs.filter((known) => known.id !== id),
  );
}

/** What one run reports as it goes. */
export interface FillProgress {
  /** Words this run set out to fill. */
  total: number;
  /** Words that have a meaning now. */
  filled: number;
  /** Words whose job has come back, filled or not. */
  settled: number;
}

export interface FillResult extends FillProgress {
  outcome: FillOutcome;
  /** The server's own words, for the address it wants confirmed. */
  message?: string;
  /** Words of the run still without a meaning afterwards. */
  left: number;
  /**
   * Of those, the ones the AI could not write (left out of a finished job,
   * or a whole job that failed as unrecognised or unusable), as the learner
   * wrote them: remembered as declined and never asked for again.
   */
  skipped: string[];
}

export interface FillOptions {
  /** Only these words (an import's own); the whole notebook otherwise. */
  ids?: ReadonlySet<string>;
  /** Whether the account's address is still unconfirmed, for how a cut-short run is said. */
  unconfirmed: boolean;
  onProgress?: (progress: FillProgress) => void;
  signal?: AbortSignal;
  now?: () => Date;
}

/**
 * Fills the words of a notebook that have no meaning, a job at a time, and
 * says how it ended. Never throws for anything the server or the network
 * does; those are outcomes.
 */
export async function fillWords(notebookId: string, options: FillOptions): Promise<FillResult> {
  const locks = globalThis.navigator.locks as LockManager | null | undefined;
  if (locks == null) return fillUnlocked(notebookId, options);
  const result = await locks.request(FILL_LOCK, { ifAvailable: true }, async (lock) =>
    lock === null ? undefined : fillUnlocked(notebookId, options),
  );
  return result ?? { outcome: 'elsewhere', total: 0, filled: 0, settled: 0, left: 0, skipped: [] };
}

async function fillUnlocked(notebookId: string, options: FillOptions): Promise<FillResult> {
  const now = options.now ?? ((): Date => new Date());
  const watchOptions = options.signal === undefined ? {} : { signal: options.signal };
  const progress: FillProgress = { total: 0, filled: 0, settled: 0 };
  const report = (): void => options.onProgress?.({ ...progress });

  const targets = await wordsToFill(notebookId, options.ids);
  progress.total = targets.length;
  report();

  // First the jobs an earlier run asked for and never poured in: their
  // words are already paid for, and asking again would pay twice.
  const remembered = (await getMeta('fillJobs')).filter((job) => job.notebookId === notebookId);
  const stillOut = new Set<string>();
  // Entries the AI did not know as words. Asking again would get the same
  // answer, so they are not sent twice in a run and are named at the end.
  const skipped: string[] = [];
  for (const stored of remembered) {
    if (now().getTime() - Date.parse(stored.at) > FORGET_JOB_AFTER_MS) {
      await forgetJob(stored.id);
      continue;
    }
    try {
      const settled = await watchJob(aiJobFromApi(await aiApi.job(stored.id)), watchOptions);
      if (settled.status === 'done') {
        progress.filled += await applyFill(notebookId, settled);
        skipped.push(...missingFrom(stored.words, settled.cards));
      } else if (isUnwritable(settled)) skipped.push(...stored.words);
      await forgetJob(stored.id);
    } catch (cause) {
      if (options.signal?.aborted === true) throw cause;
      // Gone from the server: the words are asked for again below.
      if (isApiError(cause, 'notFound')) {
        await forgetJob(stored.id);
        continue;
      }
      // Still out (offline, or slower than the watch): its words stay its own.
      for (const word of stored.words) stillOut.add(normalizeHeadword(word));
    }
    report();
  }

  const notAgain = new Set([...stillOut, ...skipped.map(normalizeHeadword)]);
  const queue = (await wordsToFill(notebookId, options.ids)).filter(
    (word) => !notAgain.has(normalizeHeadword(word.headword)),
  );
  progress.settled = progress.total - queue.length;
  report();

  let outcome: FillOutcome = 'done';
  let message: string | undefined;
  for (let start = 0; start < queue.length; start += MAX_WORDS) {
    const batch = queue.slice(start, start + MAX_WORDS).map((word) => word.headword);
    let job: AiJobView;
    try {
      // No hint, ever: a plain job is read from the shared cache and feeds it.
      job = aiJobFromApi(await aiApi.createCards(notebookId, batch, undefined, { partial: true }));
    } catch (cause) {
      await noteRefusal(cause);
      if (isRefusal(cause)) outcome = progress.filled > 0 ? 'rest' : 'resting';
      else if (isApiError(cause) && cause.code === 'email_unverified') {
        outcome = progress.filled > 0 ? 'restUnconfirmed' : 'unconfirmed';
        message = cause.message;
      } else if (isApiError(cause, 'offline')) outcome = 'offline';
      else if (isAiConsentDeclined(cause)) outcome = 'declined';
      else outcome = 'failed';
      break;
    }
    const sent = batch.filter(
      (headword) => !job.plainWords.some((plain) => normalizeHeadword(plain) === normalizeHeadword(headword)),
    );
    await rememberJob({ id: job.id, notebookId, words: sent, at: now().toISOString() });
    let settled: AiJobView;
    try {
      settled = isRunning(job) ? await watchJob(job, watchOptions) : job;
    } catch (cause) {
      if (options.signal?.aborted === true) throw cause;
      // The job carries on on the server and is remembered; the next run
      // pours it in rather than asking again.
      outcome = isApiError(cause, 'offline') ? 'offline' : 'failed';
      break;
    }
    if (settled.status === 'done') {
      progress.filled += await applyFill(notebookId, settled);
      skipped.push(...missingFrom(sent, settled.cards));
    }
    await forgetJob(job.id);
    progress.settled += sent.length;
    report();
    // Not one entry of the batch could be written (not words the AI knows,
    // or cards it wrote unusably twice): not a fault of the run, and the
    // allowance came back, so the next batch goes ahead.
    if (settled.status !== 'done' && isUnwritable(settled)) {
      skipped.push(...sent);
      continue;
    }
    if (settled.status !== 'done') {
      outcome = 'failed';
      break;
    }
    // The allowance covered only part of this batch: the rest of the
    // notebook waits too, and asking again now would only be refused.
    if (job.plainWords.length > 0) {
      outcome = options.unconfirmed ? 'restUnconfirmed' : 'rest';
      break;
    }
  }

  const leftWords = await waitingWords(notebookId, options.ids);
  // Only words still waiting: one that found a meaning meanwhile is not news.
  const waiting = new Set(leftWords.map((word) => normalizeHeadword(word.headword)));
  const named = new Set<string>();
  const stillSkipped = skipped.filter((word) => {
    const key = normalizeHeadword(word);
    if (!waiting.has(key) || named.has(key)) return false;
    named.add(key);
    return true;
  });
  await recordDeclined(notebookId, stillSkipped, now());
  return {
    ...progress,
    outcome,
    left: leftWords.length,
    skipped: stillSkipped,
    ...(message === undefined ? {} : { message }),
  };
}

/** One run, as the screens show it. */
export interface FillRun {
  notebookId: string;
  /** The words the run was limited to, as a key, so only the screen that asked shows it. */
  scope: string;
  running: boolean;
  progress: FillProgress;
  result?: FillResult;
}

interface FillStore {
  run: FillRun | undefined;
  /** Starts a run unless one is already going; the run outlives the screen that started it. */
  start: (notebookId: string, options: Omit<FillOptions, 'onProgress' | 'signal'>) => Promise<void>;
  /** Puts away a finished run's outcome. */
  clear: () => void;
}

/** The scope key of a run limited to `ids`, or of the whole notebook. */
export function fillScope(ids?: ReadonlySet<string>): string {
  return ids === undefined ? '*' : [...ids].sort().join(',');
}

export const useFill = create<FillStore>((set, get) => ({
  run: undefined,
  start: async (notebookId, options) => {
    if (get().run?.running === true) return;
    const scope = fillScope(options.ids);
    set({ run: { notebookId, scope, running: true, progress: { total: 0, filled: 0, settled: 0 } } });
    let result: FillResult;
    try {
      result = await fillWords(notebookId, {
        ...options,
        onProgress: (progress) => {
          set((state) =>
            state.run?.notebookId === notebookId && state.run.running
              ? { run: { ...state.run, progress } }
              : state,
          );
        },
      });
    } catch {
      result = { outcome: 'failed', total: 0, filled: 0, settled: 0, left: 0, skipped: [] };
    }
    set({ run: { notebookId, scope, running: false, progress: result, result } });
  },
  clear: () => {
    if (get().run?.running === true) return;
    set({ run: undefined });
  },
}));
